class Trie:
    def __init__(self):
        self.root = {}
    def insert(self, word):
        n = self.root
        for ch in word:
            n = n.setdefault(ch, {})
        n['$'] = True
    def _walk(self, s):
        n = self.root
        for ch in s:
            if ch not in n:
                return None
            n = n[ch]
        return n
    def search(self, word):
        n = self._walk(word)
        return bool(n and n.get('$'))
    def starts_with(self, prefix):
        return self._walk(prefix) is not None

def count_components(n, edges):
    parent = list(range(n))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    comps = n
    for a, b in edges:
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb
            comps -= 1
    return comps

