def value_iteration(P, R, gamma, tol=1e-10):
    V = np.zeros(P.shape[0])
    while True:
        Q = R + gamma * P @ V
        V2 = Q.max(1)
        if np.abs(V2 - V).max() < tol:
            return V2, Q.argmax(1)
        V = V2

