def pack_context(chunks, budget):
    chosen, used = set(), 0
    for i in sorted(range(len(chunks)), key=lambda i: -chunks[i][1]):
        if used + chunks[i][2] <= budget:
            chosen.add(i); used += chunks[i][2]
